const item = $input.first();
const candidates = item.json.candidates || [];
const aiText = candidates[0]?.content?.parts?.[0]?.text || '';
const finishReason = candidates[0]?.finishReason || 'UNKNOWN';

const fileName = $('Merge Text Content').first().json.fileName;
const quizTitle = $('Merge Text Content').first().json.quizTitle;
const description = $('Merge Text Content').first().json.description;

if (!aiText) {
  throw new Error(`Gemini không trả về nội dung cho file ${fileName}. Finish reason: ${finishReason}`);
}

let parsedData;
const cleanResponse = aiText.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();

function repairAndParseJSON(str) {
  try { return JSON.parse(str); } catch (e) {
    let repairedStr = str;
    let lastBoundary = repairedStr.lastIndexOf('},{')
    if (lastBoundary === -1) lastBoundary = repairedStr.lastIndexOf('}, {');
    if (lastBoundary === -1) lastBoundary = repairedStr.lastIndexOf('},\n');
    if (lastBoundary !== -1) {
      try { return JSON.parse(repairedStr.substring(0, lastBoundary + 1) + ']}'); } catch (err) {}
    }
    const questions = [];
    const regex = /{"question"\s*:\s*".+?"explanation"\s*:\s*"[^"]*"}/gs;
    let match;
    while ((match = regex.exec(str)) !== null) {
      try { questions.push(JSON.parse(match[0])); } catch(err) {}
    }
    if (questions.length > 0) return { questions };
    e.message = `${e.message} | Finish reason: ${finishReason}`;
    throw e;
  }
}

try {
  parsedData = repairAndParseJSON(cleanResponse);
} catch (e) {
  throw new Error(`Không thể parse Gemini response cho file ${fileName}\nLỗi: ${e.message}\n500 chars đầu: ${cleanResponse.substring(0, 500)}`);
}

let questions = [];
if (Array.isArray(parsedData)) questions = parsedData;
else if (parsedData.questions && Array.isArray(parsedData.questions)) questions = parsedData.questions;
else if (parsedData.quiz && Array.isArray(parsedData.quiz)) questions = parsedData.quiz;
else { for (const key in parsedData) { if (Array.isArray(parsedData[key])) { questions = parsedData[key]; break; } } }

if (questions.length === 0) {
  throw new Error(`Gemini trả về JSON nhưng không có câu hỏi nào! Finish reason: ${finishReason}`);
}

return [{ json: { fileName, quizTitle, description, questions, totalQuestions: questions.length, totalFiles: 1, finishReason } }];

