={{ (() => {
  const folderName = $('Set Variables').item.json.folderName;
  const totalQuestions = $('Parse AI Quiz Response').item.json.totalQuestions;
  const finishReason = $('Parse AI Quiz Response').item.json.finishReason;
  const folderLink = $('Set Variables').item.json.folderLink;
  return {
    chat_id: $('Set Variables').item.json.telegramChatId,
    text: [
      '❌ <b>Tạo Quiz THẤT BẠI</b>',
      '',
      '📋 <b>' + folderName + '</b>',
      '',
      '⚠️ <b>Lý do:</b> AI chỉ tạo được ' + totalQuestions + ' câu (yêu cầu ≥10).',
      '🔍 Finish reason: ' + finishReason,
      '',
      '📁 <b>Folder:</b> ' + folderLink,
      '',
      '👉 Kiểm tra nội dung file hoặc thử lại.'
    ].join('
'),
    parse_mode: 'HTML'
  };
})() }}

={{ (() => {
  const formId = $json.formId;
  const questions = $('Parse AI Quiz Response').item.json.questions;
  const description = $('Parse AI Quiz Response').item.json.description;
  const requests = [];
  if (description) {
    requests.push({ updateFormInfo: { info: { description }, updateMask: 'description' } });
  }
  requests.push({ updateSettings: { settings: { quizSettings: { isQuiz: true } }, updateMask: 'quizSettings.isQuiz' } });
  questions.forEach((q, index) => {
    const options = Object.entries(q.options || {}).map(([key, value]) => ({ value: `${key}. ${value}` }));
    const correctKey = q.correctAnswer;
    const correctOptionValue = `${correctKey}. ${(q.options || {})[correctKey]}`;
    requests.push({
      createItem: {
        item: {
          title: q.question,
          description: '',
          questionItem: {
            question: {
              required: true,
              grading: {
                pointValue: 1,
                correctAnswers: { answers: [{ value: correctOptionValue }] },
                whenRight: { text: '✅ Chính xác!' },
                whenWrong: { text: `❌ Đáp án đúng là: ${correctOptionValue}` }
              },
              choiceQuestion: { type: 'RADIO', options, shuffle: false }
            }
          }
        },
        location: { index }
      }
    });
  });
  return { requests };
})() }}

={{ (() => {
  const questions = $('Parse AI Quiz Response').item.json.questions || [];
  const folderName = $('Set Variables').item.json.folderName || 'Quiz';
  let safeSheetName = folderName.replace(/[^a-zA-Z0-9 -_]/g, ' ').trim().substring(0, 90) + ' ' + Math.floor(Math.random() * 1000);
  const sheetId = Math.floor(Math.random() * 10000000) + 10000;
  const requests = [];
  requests.push({
    addSheet: {
      properties: {
        sheetId: sheetId,
        title: safeSheetName
      }
    }
  });
  const rows = [];
  rows.push({
    values: [
      { userEnteredValue: { stringValue: "Question" } },
      { userEnteredValue: { stringValue: "Option A" } },
      { userEnteredValue: { stringValue: "Option B" } },
      { userEnteredValue: { stringValue: "Option C" } },
      { userEnteredValue: { stringValue: "Option D" } },
      { userEnteredValue: { stringValue: "Correct Answer" } },
      { userEnteredValue: { stringValue: "Explanation" } }
    ]
  });
  questions.forEach(q => {
    rows.push({
      values: [
        { userEnteredValue: { stringValue: q.question || "" } },
        { userEnteredValue: { stringValue: (q.options && q.options.A) || "" } },
        { userEnteredValue: { stringValue: (q.options && q.options.B) || "" } },
        { userEnteredValue: { stringValue: (q.options && q.options.C) || "" } },
        { userEnteredValue: { stringValue: (q.options && q.options.D) || "" } },
        { userEnteredValue: { stringValue: q.correctAnswer || "" } },
        { userEnteredValue: { stringValue: q.explanation || "" } }
      ]
    });
  });
  requests.push({
    appendCells: {
      sheetId: sheetId,
      rows: rows,
      fields: "userEnteredValue"
    }
  });
  return { requests };
})() }}

